"""A-only rejoin of retained native contents, followed by existing DAX/Runtime.

The build adds the already-used deployment functions and the checked provider
package. Private site bindings are supplied by the approved unified task.
"""
import base64,grp,hashlib,http.client,json,os,platform,re,secrets,socket,stat,struct,subprocess,sys,time,types,zlib
from pathlib import Path
PAYLOADS={'provider-package': {'bytes': 342969, 'sha256': 'f284be82e2286f2bb3c40772dc49ee53a8c7cd8c8538c74402518444914e614c', 'z64': ''}, 'proxy': {'bytes': 2792, 'sha256': 'dad85948b773699c31ca6bc3f808da8d0bebc58d9c1b25220687d1823a3fa674', 'z64': ''}}
BASE=Path('/home/jwk/root/hpra-v1')
PORT=18231
ADAPTER_SHA='34ed1c5666b5628cc37b4c75f95a44766b0cd119eb02f0df8c9ce15a54bcdfa0'
KERNEL='6.6.0-145.3.34.165.oe2403sp3.aarch64'
BYTES=1811939328
MIB=1048576
META_PREFIX=struct.Struct('<BBIII52s16sQQQ16s16sQI52s')


def unpack(encoded,limit):
    compressed=base64.b64decode(encoded,validate=True);d=zlib.decompressobj()
    raw=d.decompress(compressed,limit+1)
    need(d.eof and not d.unconsumed_tail and not d.unused_data and len(raw)<=limit,'Bounded package differs')
    return raw


def source(name):
    item=PAYLOADS[name];raw=unpack(item['z64'],item['bytes'])
    need(len(raw)==item['bytes'] and hashlib.sha256(raw).hexdigest()==item['sha256'],'Embedded checked source differs')
    return raw


def need(ok,reason):
    if not ok:raise RuntimeError(reason)

def wire(value):
    # The existing provider's manifest/config digest preserves JSON key order.
    return json.dumps(value,separators=(',',':'),ensure_ascii=False).encode()

def read(path,limit=512*1024,owners=(0,1204)):
    path=Path(path);need(path.resolve(strict=True)==path,'Input path redirected')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    with os.fdopen(fd,'rb') as f:
        a=os.fstat(f.fileno());need(stat.S_ISREG(a.st_mode) and a.st_uid in owners and a.st_size<=limit,'Input owner/type/size differs')
        data=f.read(limit+1);b=os.fstat(f.fileno())
    sig=lambda x:(x.st_dev,x.st_ino,x.st_size,x.st_mtime_ns,x.st_ctime_ns)
    need(len(data)<=limit and sig(a)==sig(b)==sig(path.stat()),'Input changed')
    return data

def digest(path):
    path=Path(path);need(path.resolve(strict=True)==path,'Hash source redirected')
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK|os.O_CLOEXEC)
    h=hashlib.sha256()
    with os.fdopen(fd,'rb') as f:
        a=os.fstat(f.fileno());need(stat.S_ISREG(a.st_mode) and a.st_size<=4*1024**3,'Hash source invalid')
        for block in iter(lambda:f.read(1024**2),b''):h.update(block)
        b=os.fstat(f.fileno())
    sig=lambda x:(x.st_dev,x.st_ino,x.st_size,x.st_mtime_ns,x.st_ctime_ns)
    need(sig(a)==sig(b)==sig(path.stat()),'Source changed during hashing')
    return h.hexdigest()

def folder(p,uid=0,gid=0,mode=0o755):
    need(p.resolve()==p,'Directory redirected')
    if not p.exists():p.mkdir(mode=mode);os.chown(p,uid,gid);os.chmod(p,mode)
    s=p.stat();need(stat.S_ISDIR(s.st_mode) and s.st_uid==uid and not stat.S_IMODE(s.st_mode)&0o022,'Directory identity differs')

def put(p,raw,uid=0,gid=0,mode=0o644):
    need(p.parent.resolve()==p.parent and not p.is_symlink(),'Output redirected')
    if p.exists():
        s=p.stat();need(s.st_uid==uid and stat.S_IMODE(s.st_mode)==mode and read(p,len(raw)+1)==raw,'Prior output differs; preserved');return
    fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,mode)
    with os.fdopen(fd,'wb') as f:
        os.fchown(f.fileno(),uid,gid);os.fchmod(f.fileno(),mode);f.write(raw);f.flush();os.fsync(f.fileno())

def tool(name):
    for prefix in ('/usr/sbin','/usr/bin','/sbin','/bin'):
        p=Path(prefix)/name
        if p.is_file():
            s=p.resolve().stat();need(s.st_uid==0 and not s.st_mode&0o022,'System tool is writable')
            return str(p)
    raise RuntimeError('Missing system tool: '+name)

def cmd(argv,seconds=60,owner=False,check=True,env=None):
    opts={'user':1204,'group':1205,'extra_groups':[grp.getgrnam('ubsmd').gr_gid],'umask':0o077} if owner else {}
    r=subprocess.run(list(map(str,argv)),stdin=subprocess.DEVNULL,capture_output=True,timeout=seconds,
        env=env or {'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','HOME':'/home/jwk','LANG':'C','LC_ALL':'C'},**opts)
    need(not check or r.returncode==0,'Command failed: '+Path(str(argv[0])).name+' exit='+str(r.returncode))
    return r

def props(name):
    r=cmd([tool('systemctl'),'show',name,'--no-pager',
        '--property=MainPID,ActiveState,LoadState,Result,ExecMainStatus,Description,User,Group,ControlGroup'])
    return dict(line.split('=',1) for line in r.stdout.decode().splitlines() if '=' in line)

def ticks(pid):return Path('/proc',str(pid),'stat').read_text().rsplit(')',1)[1].split()[19]

def zero_caps(pid):
    return all(int(line.split()[1],16)==0 for line in Path('/proc',str(pid),'status').read_text().splitlines()
               if line.startswith(('CapInh:','CapPrm:','CapEff:','CapAmb:')))

def toml(value):
    import tomllib
    lines=[]
    def emit(row,prefix):
        if prefix:lines.append('['+'.'.join(prefix)+']')
        for key,v in row.items():
            need(re.fullmatch('[A-Za-z0-9_-]+',key) is not None,'Invalid TOML key')
            if not isinstance(v,dict):lines.append(key+' = '+json.dumps(v))
        lines.append('')
        for key,v in row.items():
            if isinstance(v,dict):emit(v,prefix+[key])
    emit(value,[]);raw=('\n'.join(lines)+'\n').encode()
    need(tomllib.loads(raw.decode())==value,'TOML serialization differs');return raw

def file_digest(path,expected_bytes):
    fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
    with os.fdopen(fd,'rb') as stream:
        before=os.fstat(stream.fileno())
        if not stat.S_ISREG(before.st_mode) or before.st_size!=expected_bytes:
            raise ValueError('Dedicated experiment file length/type differs')
        sha=hashlib.sha256()
        for data in iter(lambda:stream.read(MIB),b''):sha.update(data)
        after=os.fstat(stream.fileno())
        if (before.st_dev,before.st_ino,before.st_size,before.st_mtime_ns)!=(
                after.st_dev,after.st_ino,after.st_size,after.st_mtime_ns):
            raise RuntimeError('Experiment file changed while reading')
        return sha.hexdigest()

def process_identity(pid):
    return (Path('/proc')/str(pid)/'stat').read_text().rsplit(')',1)[1].split()[19]

def decode_reference_metadata(data):
    """Decode only the fixed prefix from public ubs-engine 1.0.1 source.

    Caller must report runtime-package/source matching separately. No raw
    physical addresses, credentials or username are emitted by this decoder.
    """
    if len(data)<2+META_PREFIX.size:raise ValueError('OBMM private metadata prefix is unavailable')
    value=META_PREFIX.unpack_from(data,2)
    version,kind=value[:2]
    if version!=1 or kind!=2:raise ValueError('Not the reference version1 shared-memory metadata')
    def text(raw):
        prefix=raw.split(b'\0',1)[0]
        if not prefix:raise ValueError('Empty shared-object provenance field')
        return prefix.decode('ascii')
    return {'schema':'ubs-engine-1.0.1-custom-v1-prefix','schemaRuntimeAttested':False,
            'version':version,'kind':kind,'exportNodeId':text(value[10]),
            'exportMemId':value[12],'globalName':text(value[14]),
            'rawMetadataSha256':hashlib.sha256(data).hexdigest()}

def region_evidence(pid,ticks,ranges,runtime_attested=False,evidence_dir=None):
    if process_identity(pid)!=ticks:raise ValueError('Root helper identity differs')
    found={}
    for fd in (Path('/proc')/str(pid)/'fd').iterdir():
        try:
            target=os.readlink(fd)
            match=re.fullmatch('/dev/obmm_shmdev([0-9]+)',target)
            if not match:continue
            info=fd.stat();number=int(match[1]);root=Path('/sys/devices/obmm')/('obmm_shmdev'+str(number))
            if not stat.S_ISCHR(info.st_mode):raise ValueError('Region is not a character device')
            kind=(root/'type').read_text().strip();size=int((root/'size').read_text().strip(),0)
            row={'localRegionId':number,'kind':kind,'bytes':size,
                 'device':[os.major(info.st_rdev),os.minor(info.st_rdev)],
                 'ranges':[value for value in ranges if value['rdev']==info.st_rdev]}
            if not row['ranges']:continue
            count=int((root/'priv_len').read_text().strip())
            if not 0<count<=512:raise ValueError('Unexpected private metadata length')
            with (root/'priv').open('rb') as stream:data=stream.read(count)
            if evidence_dir is not None:
                directory=Path(evidence_dir)
                directory.mkdir(mode=0o700,exist_ok=True)
                directory_info=directory.lstat()
                if (not stat.S_ISDIR(directory_info.st_mode) or directory_info.st_uid!=0
                        or directory_info.st_mode&0o077 or directory.resolve(strict=True)!=directory):
                    raise ValueError('Private evidence directory differs')
                saved=directory/('region-'+str(number)+'-priv.bin')
                if saved.exists() or saved.is_symlink():
                    info_saved=saved.lstat()
                    if (not stat.S_ISREG(info_saved.st_mode) or info_saved.st_uid!=0 or info_saved.st_mode&0o077
                            or info_saved.st_size!=len(data) or saved.read_bytes()!=data):
                        raise ValueError('Private provenance artifact changed')
                else:
                    out=os.open(saved,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
                    with os.fdopen(out,'wb') as stream:stream.write(data);stream.flush();os.fsync(stream.fileno())
                row['privateMetadataFile']=str(saved)
            try:
                row['provenance']=decode_reference_metadata(data)
                row['provenance']['schemaRuntimeAttested']=runtime_attested is True
            except (ValueError,UnicodeError) as error:row['provenance']=None;row['reason']=str(error)
            found[number]=row
        except (OSError,ValueError) as error:
            # Missing evidence is explicit, never a positive mapping claim.
            found['fd-'+fd.name]={'provenance':None,'reason':str(error)}
    if process_identity(pid)!=ticks:raise ValueError('Root helper changed during evidence capture')
    return list(found.values())

def engine_schema(rpm,pid,ticks):
    observed={}
    try:
        if process_identity(pid)!=ticks:raise ValueError('UBSE process changed')
        exe=Path(os.readlink(Path('/proc')/str(pid)/'exe')).resolve(strict=True)
        info=exe.stat()
        if info.st_uid!=0 or info.st_mode&0o022 or not 0<info.st_size<=128*MIB:
            raise ValueError('UBSE executable ownership/size differs')
        query='%{NAME}\n%{VERSION}\n%{RELEASE}\n%{FILEDIGESTALGO}\n[%{FILENAMES}\t%{FILEDIGESTS}\n]'
        result=subprocess.run([rpm,'-qf','--qf',query,str(exe)],capture_output=True,text=True,
                              timeout=30,env={'PATH':'/usr/sbin:/sbin:/usr/bin:/bin','LANG':'C','LC_ALL':'C'})
        lines=result.stdout.splitlines()
        observed['observedPackage']=lines[:4]
        observed['executable']=str(exe)
        if result.returncode or lines[:4]!=['ubs-engine','1.0.1','1.oe2403sp3','8']:
            raise ValueError('Installed engine package does not match reviewed schema source')
        rows=dict(line.split('\t',1) for line in lines[4:] if '\t' in line)
        expected=rows.get(str(exe))
        if expected is None or not re.fullmatch('[0-9a-f]{64}',expected):raise ValueError('RPM executable digest missing')
        actual=file_digest(exe,info.st_size)
        observed['executableSha256']=actual
        if (actual!=expected or actual!='22ce7d2f4309765d18e4df41a8a2941aacd023cac46d8f135aee0cd4a2e19d45'
                or info.st_size!=9704056 or process_identity(pid)!=ticks):
            raise ValueError('Runtime executable differs from the pinned official RPM binary')
        return {'attested':True,'package':'ubs-engine-1.0.1-1.oe2403sp3','executableSha256':actual,
                'executable':str(exe),'fileIdentity':[info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns],
                'binaryRpmSha256':'e777429d01d7f99aedceafb0cf723bb39fa626c49a8d0078ea657f718b1a0e84',
                'sourceRpmSha256':'8cd3800d1056c0fa76bc36a7ebf13f513c9d094eb754cd9ce2dd459efa6efc8b'}
    except (OSError,ValueError,subprocess.SubprocessError) as error:
        return {'attested':False,'reason':str(error),**observed}

def shared_graph(first,second,image_bytes):
    """Match logical ranges to the same export node/region under pinned schema."""
    def ranges(sample):
        if not sample.get('engineSchema',{}).get('attested'):
            raise ValueError('Runtime engine schema not attested')
        result=[];capacity={}
        for row in sample.get('mappingEvidence',[]):
            meta=row.get('provenance')
            if (not meta or meta.get('schemaRuntimeAttested') is not True
                    or meta.get('version')!=1 or meta.get('kind')!=2 or row.get('kind') not in ('export','import')):
                raise ValueError('Incomplete region provenance')
            origin=(meta['exportNodeId'],row['localRegionId'] if row['kind']=='export' else meta['exportMemId'])
            if not origin[0] or origin[1]<=0:raise ValueError('Unknown export origin')
            previous=capacity.setdefault(origin,row['bytes'])
            if previous!=row['bytes']:raise ValueError('Conflicting origin region sizes')
            for region in row.get('ranges',[]):
                offset,count,logical=region['offset'],region['bytes'],region['logicalOffset']
                if min(offset,logical)<0 or count<=0 or offset+count>row['bytes']:
                    raise ValueError('Region range exceeds backing')
                result.append((logical,count,origin,offset))
        result.sort();cursor=0
        for logical,count,_,_ in result:
            if logical!=cursor:raise ValueError('Logical source ranges have holes or duplicates')
            cursor+=count
        if cursor!=image_bytes:raise ValueError('Mapping evidence does not cover the complete image')
        return result,capacity
    try:
        a,ac=ranges(first);b,bc=ranges(second)
        if a!=b:return {'matched':False,'reason':'Logical ranges refer to different export origins'}
        if ac!=bc:return {'matched':False,'reason':'Export origin capacities differ'}
        return {'matched':True,'originCount':len(ac),'referencedRegionCapacityBytes':sum(ac.values()),
                'physicalIncrementBytes':None,
                'meaning':'same exported region identities/ranges; capacity is not new physical allocation'}
    except (KeyError,TypeError,ValueError) as error:
        return {'matched':None,'reason':str(error),'physicalIncrementBytes':None}

class Rejoin:
    def __init__(self,spec):
        self.spec=spec;self.node='node-a';self.n='a';self.auth={'runId':'hpra-20261031-v1'}
        self.work=Path(spec['workDirectory']);self.active=self.work/'rejoin-r1'
        self.api=types.SimpleNamespace(digest=lambda b:hashlib.sha256(b).hexdigest(),
             encoded=lambda x:json.dumps(x,sort_keys=True,separators=(',',':')).encode())
        need(os.getuid()==os.geteuid()==0 and platform.node()=='server1','A root required')
        actual={'hostname':platform.node(),'machineId':Path('/etc/machine-id').read_text().strip(),
            'bootId':Path('/proc/sys/kernel/random/boot_id').read_text().strip(),
            'kernel':platform.release(),'architecture':platform.machine()}
        need(actual==spec['identity'],'Current A boot/kernel differs')
        need(not BASE.exists() and not BASE.is_symlink() and not self.active.exists(),'Prior rejoin intent exists; no retry')
        need(BASE.parent.resolve()==BASE.parent and BASE.parent.stat().st_uid==0 and not BASE.parent.stat().st_mode&0o022,
             'Untrusted root artifact parent')
        maintenance=json.loads(read(Path(spec['maintenanceDirectory'])/'journal.json'))
        need(maintenance['phase']=='candidate_loaded_ubse_active' and maintenance['bootId']==actual['bootId'] and
             maintenance['currentProcess']==spec['ubse'] and maintenance['candidateSha256']==spec['candidateSha256'],
             'A maintenance has not completed this exact candidate activation')
        self.plan=json.loads(read(Path(spec['planPath'])))
        need(digest(Path(spec['planPath']))==spec['planSha256'] and self.plan['workDirectory']==str(self.work),
             'Retained preparation plan differs')
        self.publication=json.loads(base64.b64decode(spec['publicationBase64'],validate=True))
        pubraw=wire(self.publication)
        need(self.api.digest(pubraw)==spec['manifestSha256'][7:] and self.publication['ownerId']==spec['ownerId'] and
             len(self.publication['replicas'])==1 and self.publication['replicas'][0]['mappingBytes']==BYTES,
             'Original publication bytes/size differ; never allocate a replacement')
        # Do not enter SDK work if another Host-facing API already uses the port.
        with socket.socket() as probe:probe.bind(('127.0.0.1',PORT))
        folder(BASE,mode=0o711);folder(BASE/'public');folder(BASE/'private',mode=0o700)
        self.state={'schema':1,'phase':'prepared','identity':actual,'steps':{},'units':{},'SDK_called':False,
                    'UBAllocated':False,'UBWritten':False,'Guest_created':False,'BChanged':False,
                    'logicalImportedBytes':BYTES,'physicalHardQuota':False,'physicalIncrementBytes':None,
                    'globalObjectDeletionAllowed':False}
        self.state['steps']['maintenance']={'state':'done','result':maintenance}
        self.mark('prepared')

    def python(self,name,*args):
            bootstrap="import sys,runpy;sys.path.insert(0,sys.argv.pop(1));m=sys.argv.pop(1);sys.argv[0]=m;runpy.run_module(m,run_name='__main__')"
            return ['/usr/bin/python3','-I','-B','-c',bootstrap,str(BASE/'code'),name,*map(str,args)]

    def bound(self,label):
            row=self.state['units'][label];p=props(row['name'])
            need(row.get('pid') and p['ActiveState']=='active' and int(p['MainPID'])==row['pid'] and
                p['Description']==row['description'] and ticks(row['pid'])==row['ticks'],'Owned '+label+' process changed')
            return row

    def _launch(self,label,argv,extra):
            name='aenv-hpra-'+self.n+'-'+label+'-'+self.auth['runId'][-8:]+'.service'
            need(props(name)['LoadState']=='not-found','New unit name already exists')
            row={'name':name,'description':'AgentENV Host DAX '+self.auth['runId']+' '+self.node+' '+label,
                 'argvSha256':self.api.digest(self.api.encoded(argv)),'launchIntent':True}
            self.state['units'][label]=row;self.mark(label+'_unit_launch_intent')
            common=['Type=exec','Restart=no','UMask=0077','KillMode=control-group','TimeoutStopSec=90',
                'LimitNOFILE=65536','LimitCORE=0','StandardOutput=journal','StandardError=journal',
                'WorkingDirectory=/','Description='+row['description']]
            cmd([tool('systemd-run'),'--quiet','--unit='+name,*['--property='+x for x in common+extra],'--',*argv])
            p=props(name);need(p['ActiveState']=='active' and int(p['MainPID'])>0,'Unit start not confirmed')
            row.update(pid=int(p['MainPID']),ticks=ticks(int(p['MainPID'])));self.mark(label+'_unit_started')
            return row

    def ready(self,label,path,key,value,seconds=1200):
            end=time.monotonic()+seconds
            while time.monotonic()<end:
                self.bound(label)
                if path.exists():
                    r=json.loads(read(path))
                    if r.get(key)==value:return r
                    need(r.get(key) not in ('unresolved_preserved','stopped_preserve_resources',
                          'rootfs_stopped_preserve_resources','unresolved_create'),'Helper reported preserved failure')
                time.sleep(1)
            raise RuntimeError('Helper readiness not confirmed; preserve, never relaunch SDK')

    def candidate_live(self):
            need(Path('/sys/module/obmm/srcversion').read_text().strip()=='C2BBB64D75C618180ABA3A6' and
                Path('/sys/module/obmm/parameters/pmem_ro_enable').read_text().strip()=='Y','Candidate context changed')
            row=self.state['steps']['maintenance']['result']['currentProcess']
            need(props('ubse.service')['MainPID']==str(row['pid']) and ticks(row['pid'])==row['ticks'],'UBSE changed')

    def permissions(self):
            acl=[]
            for name in ('obmm','ublk-control'):
                path=Path('/dev')/name;s=path.stat()
                old=cmd([tool('getfacl'),'-p',str(path)]).stdout
                backup=BASE/'private'/(name+'.acl');put(backup,old,mode=0o600)
                row={'path':str(path),'inode':s.st_ino,'rdev':s.st_rdev,'backup':str(backup),
                     'beforeSha256':self.api.digest(old)}
                acl.append(row);self.state['acl']=acl;self.mark('device_acl_intent')
                cmd([tool('setfacl'),'-m','u:1204:rw',str(path)])
                row['appliedSha256']=self.api.digest(cmd([tool('getfacl'),'-p',str(path)]).stdout)
                self.mark('device_acl_applied')
            return {'acl':acl,'udevRuleInstalled':False}

    def view(self):
            from aenv_ub_provider import host_pmem_rootfs,stored,contract
            sdk=self.state['steps']['sdk']['result'];publication=sdk['publication'];owner=self.bound('sdk')
            source_spec={**publication['replicas'][0]['identity'],'socket':str(self.active/'provider/data.sock')}
            files=[]
            for f in self.plan['layers']:
                if f['kind']!='rootfs':continue
                files.append({'name':f['digest'][7:]+'.commit','replica':{
                    'brokerSocket':str(self.active/'lower.sock'),'objectName':'aenv_'+secrets.token_hex(16),
                    'generation':secrets.token_hex(16),'layerDigest':f['digest'],'fileBytes':f['bytes'],
                    'mappingBytes':((f['bytes']+stored.HEADER_BYTES+stored.ALIGN-1)//stored.ALIGN)*stored.ALIGN,
                    'allowRepositoryFallback':False}})
            cfg={'version':1,'workDir':str(BASE/'view'),'source':source_spec,'ownerUid':1204,
                'ownerPid':owner['pid'],'ownerStartTicks':owner['ticks'],'publication':publication,
                'releaseReceipt':str(BASE/'public/local-release.json'),'kernelRelease':KERNEL,
                'moduleSrcversion':'C2BBB64D75C618180ABA3A6','files':files,'brokerSocket':str(self.active/'lower.sock'),
                'brokerGid':1205,'runtimeIndex':str(BASE/'public/rootfs-index.json'),'payloadResponses':2}
            plan=host_pmem_rootfs.plan(cfg);put(BASE/'private/rootfs-config.json',contract.canonical(cfg),mode=0o600)
            self.state['viewConfigSha256']=plan['configSha256'];self.mark('rootfs_view_intent')
            self.launch('view',self.python('aenv_ub_provider.host_pmem_rootfs','serve','--config',BASE/'private/rootfs-config.json',
                '--expected-config-sha256',plan['configSha256'],'--approval','CREATE_READONLY_ROOTFS_HOST_PMEM'),
                ['PrivateMounts=yes','CapabilityBoundingSet=CAP_SYS_ADMIN CAP_SETUID CAP_SETGID CAP_DAC_READ_SEARCH','MemoryMax=6G'])
            record=self.ready('view',BASE/'view/host-pmem-session.json','phase','rootfs_broker_ready')
            evidence=record.get('rootfsBroker',{}).get('fileEvidence',[])
            need(len(evidence)==8 and all(x['activeDax'] and x['readonlyMount'] for x in evidence),
                 'Actual DAX file binding not confirmed')
            index=json.loads(read(BASE/'public/rootfs-index.json'))
            need(len(index['replicas'])==8 and all(x['allowRepositoryFallback'] is False for x in index['replicas']),
                 'Required DAX runtime index differs')
            return {'configSha256':plan['configSha256'],'journal':record,'indexSha256':digest(BASE/'public/rootfs-index.json')}

    def runtime(self):
            self.candidate_live();self.bound('sdk');self.bound('view')
            source_base=Path(self.plan['sourceDeployment']);deps=self.active/'deps'
            # Reuse dependency payloads; only small configs are independently copied.
            # No rootfs/memory lower payload is copied or linked here.
            count=total=0
            for p in sorted((source_base/'deps').rglob('*')):
                need(p.resolve(strict=True)==p,'Dependency symlink refused')
                relative=p.relative_to(source_base/'deps');dest=deps/relative
                if p.is_dir():folder(dest,1204,1205,0o700);continue
                s=p.stat();need(stat.S_ISREG(s.st_mode) and s.st_uid==1204,'Unexpected dependency owner/type')
                count+=1;total+=s.st_size;need(count<=2048 and total<=3*1024**3,'Dependency budget exceeded')
                if str(relative)=='overlaybd/etc/overlaybd/overlaybd.json':continue
                need(not dest.exists(),'Dependency export already exists; preserve partial runtime')
                if p.suffix=='.json':put(dest,read(p,2*1024**2),1204,1205,0o600)
                else:os.link(p,dest)
            overlay=deps/'overlaybd/etc/overlaybd'
            for p in (deps/'overlaybd',deps/'overlaybd/etc',overlay):folder(p,1204,1205,0o700)
            clean={'logConfig':{'logLevel':1,'logPath':str(self.active/'logs/overlaybd.log')},
                'cacheConfig':{'cacheType':'file','cacheDir':str(self.active/'state/overlaybd-cache'),
                               'cacheSizeGB':1,'refillSize':262144,'blockSize':65536},
                'credentialFilePath':'','credentialConfig':{},'ioEngine':0,
                'p2pConfig':{'enable':False},'enableAudit':False,'registryFsVersion':'v2'}
            put(overlay/'overlaybd.json',json.dumps(clean).encode(),1204,1205,0o600)
            cfg={'home_path':str(self.active/'state'),'runtime_path':str(self.active/'run'),
                'deps_path':str(deps),'virtualization_mode':'kvm',
                'firecracker':{'binary_path':str(deps/'firecracker/1.15.1-patch-v3/firecracker'),
                    'work_dir':str(self.active/'fc'),'serial_dir':str(self.active/'logs'),'log_level':'Info'},
                'kernel':{'image_path':str(deps/'kernel/vmlinux-6.1.175/vmlinux.bin')},
                'tools':{'version':'0.1.1','drive_path':str(deps/'tools/0.1.1/tools.ext4')},
                'snapshot':{'repository_backend':'posix_fs','p2p_enabled':False,
                    'ub_rootfs_index':str(BASE/'public/rootfs-index.json'),
                    'ub_rootfs_index_sha256':self.state['steps']['view']['result']['indexSha256']},
                'backend':{'posix_fs':{'snapshot_store':str(self.work/'seed')}},
                'ublk':{'daemon_binary_path':self.plan['binaries']['bin/uvm-ublk-daemon']['path'],
                    'daemon_socket_path':str(self.active/'run/ublk.sock'),'daemon_log_path':str(self.active/'logs/ublk.log'),
                    'daemon_metrics_listen_addr':''},'image':{'cache':{'gc':{'enabled':False}}},'p2p':{'enabled':False},
                'pool':{'network':{'maintenance_enabled':False},'block':{'enabled':False,'startup_prewarm':False},
                        'firecracker':{'enabled':False,'startup_prewarm':False}},'observability':{'enabled':False},
                'node_identity':{'node_id':'host-dax-'+self.n,'cluster_id':self.auth['runId'],
                                 'service_instance_id':'hpab-'+self.n+'-runtime'}}
            # Check actual Linux sun_path budget, not only the path prefix.
            need(len(os.fsencode(self.active/'fc/agentenv-fc-XXXXXX/firecracker.socket'))<=107,'FC socket budget exceeded')
            put(BASE/'public/runtime.toml',toml(cfg))
            key='e2b_'+secrets.token_hex(24)
            put(self.active/'cli/aenv/credentials',('url = "http://127.0.0.1:18231"\napi_key = '+json.dumps(key)+'\n').encode(),1204,1205,0o600)
            put(BASE/'private/runtime.env',('AENV_API_KEY='+key+'\nAPI_ADDR=127.0.0.1:18231\n'
                'AENV_CONFIG_PATH='+str(BASE/'public/runtime.toml')+'\n'
                'HOME=/home/jwk\nAENV_HOME_PATH='+str(self.active/'state')+'\n'
                'AENV_DEPS_PATH='+str(deps)+'\nAENV_RUNTIME_PATH='+str(self.active/'run')+'\n'
                'PATH='+str(source_base/'native/bin')+':/usr/sbin:/usr/bin:/sbin:/bin\n'
                'LD_LIBRARY_PATH='+str(source_base/'native/lib')+':'+str(source_base/'native/fallback/lib')+'\n'
                'XTABLES_LIBDIR='+str(source_base/'native/xtables')+'\n'
                'TMPDIR='+str(self.active/'tmp')+'\nXDG_CACHE_HOME='+str(self.active/'cache')+'\n').encode(),mode=0o600)
            before=os.stat('/proc/self/ns/net').st_ino
            prestart=('import os\nfrom pathlib import Path\nassert os.geteuid()==0\n'
                'assert os.stat("/proc/self/ns/net").st_ino != '+str(before)+'\n'
                'Path("/proc/sys/net/ipv4/ip_forward").write_text("1\\n")\n').encode()
            put(BASE/'public/runtime-prestart.py',prestart)
            server=self.plan['binaries']['bin/server']['path']
            row=self.launch('runtime',[server],['User=1204','Group=1205','SupplementaryGroups=ubsmd kvm',
                'AmbientCapabilities=CAP_SYS_ADMIN CAP_NET_ADMIN','CapabilityBoundingSet=CAP_SYS_ADMIN CAP_NET_ADMIN',
                'PrivateNetwork=yes','PrivateMounts=yes','EnvironmentFile='+str(BASE/'private/runtime.env'),
                'ExecStartPre=+/usr/bin/python3 -I -B '+str(BASE/'public/runtime-prestart.py'),
                'BindReadOnlyPaths='+self.plan['sourceManagedLayers']+':'+self.plan['privateReadonlyBindTarget']+' '+
                    str(self.work/'seed/repository/catalog')+' '+str(self.work/'seed/repository/snapshots')])
            end=time.monotonic()+90
            while time.monotonic()<end:
                self.bound('runtime')
                check=cmd([tool('nsenter'),'-t',str(row['pid']),'-n','--',tool('curl'),'-sS','--max-time','3',
                    '-o','/dev/null','-w','%{http_code}','http://127.0.0.1:18231/health'],10,check=False)
                if check.returncode==0 and check.stdout==b'204':break
                time.sleep(1)
            else:raise RuntimeError('Runtime health not confirmed; backing retained')
            return {'unit':row,'health':204,'configSha256':digest(BASE/'public/runtime.toml'),
                    'binarySha256':self.plan['binaries']['bin/server']['sha256'],
                    'privateNetwork':True,'HostForwardingChanged':False}

    def proxies(self):
            rt=self.bound('runtime')
            config={'port':PORT,'socket':str(self.active/'api.sock')}
            put(BASE/'public/proxy.json',self.api.encoded(config));put(BASE/'public/proxy.py',source('proxy'))
            common=['User=1204','Group=1205','NoNewPrivileges=yes','CapabilityBoundingSet=','AmbientCapabilities=']
            self.launch('inside-proxy',['/usr/bin/python3','-I','-B',str(BASE/'public/proxy.py'),'inside',str(BASE/'public/proxy.json')],
                common+['PrivateNetwork=yes','JoinsNamespaceOf='+rt['name']])
            end=time.monotonic()+15
            while not (self.active/'api.sock').exists() and time.monotonic()<end:
                self.bound('inside-proxy');time.sleep(.2)
            need((self.active/'api.sock').exists(),'Inside API proxy socket not ready')
            self.launch('host-proxy',['/usr/bin/python3','-I','-B',str(BASE/'public/proxy.py'),'host',str(BASE/'public/proxy.json')],common)
            end=time.monotonic()+20
            while time.monotonic()<end:
                self.bound('host-proxy');self.bound('inside-proxy')
                try:
                    c=http.client.HTTPConnection('127.0.0.1',PORT,timeout=3);c.request('GET','/health')
                    r=c.getresponse();body=r.read(4096);c.close()
                    if r.status==204 and body==b'':break
                except OSError:pass
                time.sleep(.5)
            else:raise RuntimeError('Host API proxy health not confirmed')
            need(zero_caps(self.bound('host-proxy')['pid']) and zero_caps(self.bound('inside-proxy')['pid']),
                 'API proxy capabilities differ')
            env={'PATH':'/usr/sbin:/usr/bin:/sbin:/bin','HOME':'/home/jwk','LANG':'C','LC_ALL':'C',
                 'LD_LIBRARY_PATH':str(Path(self.plan['sourceDeployment'])/'native/lib')+':'+
                                   str(Path(self.plan['sourceDeployment'])/'native/fallback/lib'),
                 'XDG_CONFIG_HOME':str(self.active/'cli')}
            check=cmd([self.plan['binaries']['bin/aenv']['path'],'list','--output','json'],30,owner=True,env=env)
            need(json.loads(check.stdout)==[],'New Runtime is not empty; preserve consumers')
            wrapper=('#!/bin/sh\nexport HOME=/home/jwk\nexport XDG_CONFIG_HOME='+str(self.active/'cli')+'\n'
                'export LD_LIBRARY_PATH='+str(Path(self.plan['sourceDeployment'])/'native/lib')+':'+
                str(Path(self.plan['sourceDeployment'])/'native/fallback/lib')+'\n'
                'exec '+self.plan['binaries']['bin/aenv']['path']+' "$@"\n').encode()
            put(self.active/'aenv-host-dax',wrapper,1204,1205,0o700)
            return {'api':'http://127.0.0.1:18231','health':204,'CLI':str(self.active/'aenv-host-dax'),
                    'initialSandboxCount':0,'Guest_created':False,'guestCreationEnabled':False}

    def mark(self,phase):
        self.state['phase']=phase
        putname=BASE/'private/state.json';tmp=putname.with_name('state.next')
        fd=os.open(tmp,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
        with os.fdopen(fd,'wb') as f:f.write(self.api.encoded(self.state));f.flush();os.fsync(f.fileno())
        os.replace(tmp,putname)
        fd=os.open(putname.parent,os.O_RDONLY|os.O_DIRECTORY)
        try:os.fsync(fd)
        finally:os.close(fd)
        print('PHASE=node-a:'+phase,flush=True)

    def once(self,key,action):
        need(key not in self.state['steps'],'Existing step intent; no retry')
        self.state['steps'][key]={'state':'intent'};self.mark(key+'_intent')
        result=action();self.state['steps'][key]={'state':'done','result':result};self.mark(key+'_done')
        return result

    def export_code(self):
        package=json.loads(source('provider-package'))
        folder(BASE/'code');folder(BASE/'code/aenv_ub_provider')
        for name,item in package.items():
            need(re.fullmatch('aenv_ub_provider/[a-z_]+\\.py',name) is not None,'Unexpected source package member')
            raw=base64.b64decode(item['base64'],validate=True)
            need(hashlib.sha256(raw).hexdigest()==item['sha256'],'Checked package member differs')
            put(BASE/'code'/name,raw)
        adapter=Path('/home/jwk/agent/r/lazy4-a-v1/libaenv-ub.so')
        need(digest(adapter)==ADAPTER_SHA,'Existing native adapter changed')
        sdk_library=Path('/usr/lib64/libubsm_sdk.so').resolve(strict=True)
        sdk_sha=digest(sdk_library)
        need(sdk_sha=='88686bc4e869c6442eb7d88128a2d3efd82468696c489734fc80b4692ac60223','Installed SDK library changed')
        put(BASE/'public/libaenv-ub.so',read(adapter,1024**2),gid=1205,mode=0o640)
        for row in list(self.plan['binaries'].values())+list(self.plan['dependencies'].values()):
            need(digest(Path(row['path']))==row['sha256'],'Retained executable/dependency changed')
        folder(self.active,1204,1205,0o700)
        for name in ('state','logs','config','cache','tmp','deps','fc','run','cli','cli/aenv'):
            folder(self.active/name,1204,1205,0o700)
        return {'packageSha256':PAYLOADS['provider-package']['sha256'],'adapterSha256':ADAPTER_SHA,
                'sdkLibrarySha256':sdk_sha,'nativeBuild':False}

    def sdk(self):
        self.candidate_live();owner=self.active/'provider'
        need(not owner.exists(),'Previous SDK rejoin outcome exists; preserve without retry')
        put(BASE/'public/publisher.json',wire(self.publication))
        permit=self.spec['permit']
        permitraw=self.api.encoded(permit)
        put(BASE/'public/rejoin-permit.json',permitraw)
        cfg={'version':1,'mode':'pmem','role':'rejoin','workDir':str(owner),
            'adapter':str(BASE/'public/libaenv-ub.so'),'adapterSha256':'sha256:'+ADAPTER_SHA,
            'region':'default','logicalBudgetBytes':BYTES,'maxCoverageBytes':4294967296,
            'hostPmemReleaseReceipt':str(BASE/'public/local-release.json'),
            'readerId':permit['readerId'],'manifest':str(BASE/'public/publisher.json'),
            'rejoinPermit':str(BASE/'public/rejoin-permit.json'),'rejoinPermitSha256':'sha256:'+self.api.digest(permitraw)}
        put(BASE/'public/sdk-config.json',self.api.encoded(cfg))
        self.state['SDK_called']=None;self.mark('sdk_rejoin_start_intent')
        self.launch('sdk',self.python('aenv_ub_provider','serve',BASE/'public/sdk-config.json','--run'),
            ['User=1204','Group=1205','SupplementaryGroups=ubsmd','NoNewPrivileges=yes',
             'CapabilityBoundingSet=','AmbientCapabilities=','LimitMEMLOCK=4294967296','MemoryMax=6G'])
        record=self.ready('sdk',owner/'owner.json','state','serving')
        observed=json.loads(read(owner/'replicas.json'))
        need(observed==self.publication and record['role']=='rejoin' and record['globalObjectDeletionAllowed'] is False
             and not record.get('objects') and record.get('imports') and all(r['mapped'] for r in record['imports'])
             and record['manifestSha256']==self.spec['manifestSha256'],'Read-only rejoin did not preserve the original object')
        need(zero_caps(self.bound('sdk')['pid']),'SDK worker has unexpected capabilities')
        self.state['SDK_called']=True
        return {'publication':observed,'ownerJournal':record,'process':self.bound('sdk'),'UBAllocated':False}

    def launch(self,label,argv,extra):
        if label=='runtime':
            # Reuse the already exercised ordinary-user env loader. systemd
            # previously failed to read this service's EnvironmentFile.
            env={}
            for line in read(BASE/'private/runtime.env').decode().splitlines():
                if line:
                    k,v=line.split('=',1);need(re.fullmatch('[A-Z_][A-Z0-9_]*',k) is not None and '\0' not in v,'Bad Runtime environment')
                    env[k]=v
            put(self.active/'runtime-env.json',self.api.encoded(env),1204,1205,0o600)
            bootstrap='import json,os,sys;env=json.load(open(sys.argv[1]));exe=sys.argv[2];os.execve(exe,[exe],env)'
            argv=['/usr/bin/python3','-I','-B','-c',bootstrap,str(self.active/'runtime-env.json'),*argv]
            before=os.stat('/proc/self/ns/net').st_ino
            pre='import os;from pathlib import Path;assert os.geteuid()==0;assert os.stat("/proc/self/ns/net").st_ino!='+str(before)+';Path("/proc/sys/net/ipv4/ip_forward").write_text("1\\n")'
            inline='import base64;exec(base64.b64decode("'+base64.b64encode(pre.encode()).decode()+'"))'
            extra=[x for x in extra if not x.startswith(('EnvironmentFile=','ExecStartPre='))]
            extra+=['ExecStartPre=+/usr/bin/python3 -I -B -c '+json.dumps(inline)]
        return self._launch(label,argv,extra)

    def execute(self):
        self.once('code',self.export_code)
        self.once('permissions',self.permissions)
        self.once('sdk',self.sdk)
        self.once('view',self.view)
        self.once('provenance',self.provenance)
        self.once('runtime',self.runtime)
        self.once('proxies',self.proxies)
        self.mark('A_REJOINED_DAX_RUNTIME_HEALTHY_NO_GUEST')
        print('BEGIN_A_REJOIN_RESULT_JSON',flush=True)
        print(json.dumps(self.state,sort_keys=True),flush=True)
        print('END_A_REJOIN_RESULT_JSON',flush=True)
        print('A_REJOINED_DAX_RUNTIME_HEALTHY_NO_GUEST',flush=True)

    def provenance(self):
        sdk=self.bound('sdk');ubse=self.spec['ubse']
        schema=engine_schema(tool('rpm'),ubse['pid'],ubse['ticks'])
        need(schema.get('attested') is True,'Current UBSE provenance schema not attested')
        ranges=self.state['steps']['view']['result']['journal']['volume']['segments']
        folder(BASE/'private/regions',mode=0o700)
        rows=region_evidence(sdk['pid'],sdk['ticks'],ranges,True,BASE/'private/regions')
        name=self.publication['replicas'][0]['objectName']
        need(rows and all(r.get('provenance',{}).get('globalName')==name for r in rows),
             'Mapped regions are not the retained SDK object')
        observed={'engineSchema':schema,'mappingEvidence':rows}
        graph=shared_graph(observed,self.spec['peerEvidence'],BYTES)
        need(graph['matched'] is True,'Retained B export ranges do not match new A imports')
        need(all(r['kind']=='import' for r in rows),'A is not the expected remote reader of retained B regions')
        return {**observed,'sharedGraph':graph,'AClassifiedRemote':True,
            'samplingScope':'new A mapping matched against previously verified retained B sample; B not resampled in this task',
            'physicalIncrementBytes':None}


def main():
    raw=unpack(''.join(sys.argv[1:]),65536);spec=json.loads(raw)
    ctx=None
    try:
        ctx=Rejoin(spec);ctx.execute()
        return 0
    except Exception as error:
        detail={'status':'A_REJOIN_STOPPED_PRESERVE_STATE','errorType':type(error).__name__,
            'reason':str(error)[:1000],'automaticRetry':False,'globalObjectDeletionAllowed':False}
        if ctx is not None:
            ctx.state['failure']=detail
            try:ctx.mark('stopped_preserve_state')
            except Exception:pass
            detail['units']={k:props(v['name']) for k,v in ctx.state['units'].items()}
            if (ctx.active/'provider/owner.json').is_file():
                detail['sdkOwnerJournal']=json.loads(read(ctx.active/'provider/owner.json'))
            detail['workerDiagnostics']={}
            for label in ('sdk','view'):
                if label in ctx.state['units']:
                    p=cmd([tool('journalctl'),'-u',ctx.state['units'][label]['name'],'-n','30','--no-pager','-o','cat'],30,check=False)
                    detail['workerDiagnostics'][label]=p.stdout[-12000:].decode(errors='replace')
        print(json.dumps(detail,sort_keys=True),flush=True)
        return 1


# BUILD inserts the reused, tested deployment functions/methods above main.
if __name__=='__main__':raise SystemExit(main())
